window.docContents[195].resolve({"/Hoare2/#Hoare2":{"contents":"open scoped Com MyGetElem Assertion HasTriple\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nOn a piece of paper (or whatever), write down a Hoare-triple\nspecification for the following program:X := 2;\nY := X + X\n\n\nWrite down a (useful) specification for the following program:X := X + 1; Y := X + 1\n\n\nWrite down a (useful) specification for the following program:if X <= Y then\n  skip\nelse\n  Z := X;\n  X := Y;\n  Y := Z\nend\n\n\nWrite down a (useful) specification for the following program:X := m;\nY := X + X\n\n\nWrite down a (useful) specification for the following program:X := m;\nZ := 0;\nwhile X <> 0 do\n  X := X - 2;\n  Z := Z + 1\nend\n\n\n\n\n\n\n\n\n\n\n","context":"Hoare Logic","header":"6. Hoare2: Hoare Logic, Part II","id":"/Hoare2/#Hoare2"}});